package alcaldedigital.mision8;
import alcaldedigital.cliente.*;import alcaldedigital.cliente.mision8.*;import alcaldedigital.compartido.guardado.*;import alcaldedigital.servidor.sesion.*;import processing.core.*;import java.awt.Font;import java.nio.file.*;import java.util.*;
/** Capturas del mismo renderer con fixtures explícitos; nunca abre el perfil real. */
public final class RevisionOcho extends PApplet {
 private MisionOchoVista vista;private String caso;private int animTicks;
 public void settings(){size(1280,720,JAVA2D);noSmooth();}
 public void setup(){try{
  if(System.getProperty("ad.guardados")==null)throw new IllegalStateException("La revisión exige un perfil temporal");
  caso=System.getProperty("ad.m8.caso","config");frameRate(30);try(var in=getClass().getResourceAsStream("/cliente/fuentes/PixelifySans.ttf")){textFont(new PFont(Font.createFont(Font.TRUETYPE_FONT,in).deriveFont(18f),false));}
  var progreso=new ProgresoMisiones(ArchivosPartida.directorio());if(caso.startsWith("libre"))progreso.desbloquearTodas();else for(int i=1;i<=7;i++){progreso.victoria(i);Map<String,Integer>s=switch(i){case 1->Map.of("publicaciones_responsables",3,"burlas",0);case 2->Map.of("equipos_seguros",6,"fallo_critico",0);case 3->Map.of("confianza_final",70,"desinformacion_final",20);case 4->Map.of("respuestas_favorables",3,"respuestas_desfavorables",0,"respuestas_neutrales",1);case 5->Map.of("publicaciones_verificadas",4,"rumores",0);case 6->Map.of("respuestas_escucha",2,"respuestas_conviccion",1);default->Map.of("juan_corrupto",0,"noticias_contrastadas",4);};TablaPuntajes.registrar(new TablaPuntajes.Fila(i,"fixture-"+i,true,85,"NORMAL",List.of(),List.of(),List.of(0,3,0,0,0,0,0),s));}
  var juego=new JuegoCliente(SesionLocal::new,SesionMisionUnoLocal::new);
  if(!caso.equals("config")&&!caso.startsWith("libre")){int candidato=caso.matches(".*-[0-3]")?Integer.parseInt(caso.substring(caso.length()-1)):caso.startsWith("otro")?2:0;MotorOcho m=MisionOchoTest.combate(candidato,false,3,1,0);if(caso.startsWith("infeccion-")){m.escena=MotorOcho.Escena.MUTACION;m.lineaDialogo=HistoriaOcho.lineas(m).size()-1;m.ticksDialogo=Integer.getInteger("ad.m8.tick",48);m.textoRevelado=true;}else if(caso.equals("reposo")){m.escena=MotorOcho.Escena.REVELACION;m.lineaDialogo=1;m.ticksDialogo=200;m.textoRevelado=true;}else if(caso.startsWith("ataque-")||caso.startsWith("forma-")){m.fase=caso.startsWith("forma-")?Integer.parseInt(caso.substring(6))*2-1:1;m.forma=m.fase<3?1:m.fase<5?2:3;m.vidaJefe=(int)(m.maxVida*(m.fase==1?1:m.fase==3?.65:.3));m.iniciarAtaque(caso.startsWith("ataque-")?MotorOcho.Ataque.valueOf(caso.substring(7).toUpperCase()):MotorOcho.Ataque.ORBES);for(int t=0;t<Integer.getInteger("ad.m8.tick",80);t++)m.paso();}else if(caso.startsWith("vuelo")||caso.startsWith("inyeccion")||caso.equals("desaparicion")){m.escena=MotorOcho.Escena.MUTACION;m.inyectado=false;var accion=caso.startsWith("vuelo")?HistoriaOcho.Accion.VUELO:caso.startsWith("inyeccion")?HistoriaOcho.Accion.INYECTAR:HistoriaOcho.Accion.DESAPARECER;var lineas=HistoriaOcho.lineas(m);for(int i=0;i<lineas.size();i++)if(lineas.get(i).accion()==accion)m.lineaDialogo=i;m.ticksDialogo=0;for(int t=0;t<50;t++)m.paso();m.textoRevelado=true;}else if(caso.startsWith("dialogo")){m.escena=MotorOcho.Escena.REVELACION;m.lineaDialogo=caso.endsWith("palomo")?4:1;m.ticksDialogo=200;m.textoRevelado=true;}else if(caso.equals("tarima")){m.escena=MotorOcho.Escena.ESCRUTINIO;m.lineaDialogo=3;m.ticksDialogo=200;}else if(caso.startsWith("epilogo-")){m.escena=MotorOcho.Escena.EPILOGO;var accion=caso.endsWith("acercamiento")?HistoriaOcho.Accion.ACERCARSE:caso.endsWith("recuperacion")?HistoriaOcho.Accion.RECUPERAR:HistoriaOcho.Accion.DISPARAR;var lineas=HistoriaOcho.lineas(m);for(int i=0;i<lineas.size();i++)if(lineas.get(i).accion()==accion)m.lineaDialogo=i;m.ticksDialogo=0;m.candidatoRecuperado=accion==HistoriaOcho.Accion.DISPARAR;for(int t=0;t<(caso.endsWith("neutralizacion")?75:caso.endsWith("pulso")?40:70);t++)m.paso();m.textoRevelado=true;}else if(caso.equals("obra")){m=new MotorOcho(m.antecedentes,3,1,0,false,1);m.lineaDialogo=2;m.ticksDialogo=140;}else if(caso.equals("auditoria")){m=new MotorOcho(m.antecedentes,3,1,0,false,1);m.escena=MotorOcho.Escena.AUDITORIA;}else if(caso.equals("voto")){m.escena=MotorOcho.Escena.VOTO;Arrays.fill(m.votos,-1);m.votosEmitidos=0;}else if(caso.equals("escrutinio"))m.escena=MotorOcho.Escena.ESCRUTINIO;else if(caso.equals("mutacion")){m.escena=MotorOcho.Escena.MUTACION;m.lineaDialogo=HistoriaOcho.lineas(m).size()-1;m.ticksDialogo=110;}else if(caso.equals("final")||caso.equals("otro-final")){m.escena=MotorOcho.Escena.EPILOGO;MisionOchoTest.cerrarConversacion(m);}else if(caso.equals("derrota")){m.escena=MotorOcho.Escena.DERROTA;for(var h:m.heroes)h.vida=0;}else if(caso.startsWith("fase")){m.fase=Integer.parseInt(caso.substring(4));m.forma=m.fase<3?1:m.fase<5?2:3;if(m.fase==5){for(var h:m.heroes){h.y=-450;h.x=400;}m.camara=-790;m.jefeY=-600;}m.iniciarAtaque(MotorOcho.Ataque.ORBES);for(int i=0;i<105;i++)m.paso();m.vidaJefe=(int)(m.maxVida*(m.fase==1?1:m.fase==2?.8:m.fase==3?.65:m.fase==4?.5:.3));if(m.fase==5){for(var h:m.heroes){h.y=-450;h.x=400;h.invulnerable=0;}m.camara=-790;m.jefeY=-600;}}
   GuardadoOcho.guardar(m);juego.continuarGuardado=true;
  }
  vista=new MisionOchoVista(juego);vista.iniciarEn(this);if(caso.equals("libre-petrosqui"))vista.elegirFinal(1);if(!caso.equals("config")&&!caso.startsWith("libre")){vista.dibujar();vista.raton(200,620);}if(caso.equals("consulta"))vista.abrirConsultaComun();
 }catch(Exception e){throw new IllegalStateException(e);}}
 public void draw(){
  String secuencia=System.getProperty("ad.m8.secuencia");if(secuencia!=null){int paso=Integer.getInteger("ad.m8.paso",2);
   var m=vista.motor();if(caso.startsWith("infeccion-")){m.ticksDialogo=animTicks;m.ticks=animTicks;}
   else if(caso.equals("reposo")){m.ticks+=paso;}else{for(int t=0;t<paso;t++)m.paso();}
   vista.dibujar();get().save(secuencia+"/"+String.format("%03d.png",frameCount));animTicks+=paso;
   if(frameCount==Integer.getInteger("ad.m8.frames",75)){vista.close();System.out.println("MISION8_RENDER_OK "+caso);exit();}return;
  }
  vista.dibujar();if(frameCount==5){String ruta=System.getProperty("ad.m8.captura");if(ruta==null||!get().save(ruta))throw new IllegalStateException("Captura fallida");vista.close();System.out.println("MISION8_RENDER_OK "+caso);exit();}}
 public static void main(String[]args){PApplet.main(RevisionOcho.class.getName());}
}
